INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76770, 'spa', 'Servir como soldado', 'Servir como soldado, desempeñar el oficio militar en sentido literal o analógico. En Lucas 3:14 los soldados (οἱ στρατευόμενοι) piden consejo ético a Juan el Bautista; aquí la palabra simplemente denota el servicio militar profesional. Pablo la extiende analógicamente en 1 Corintios 9:7 (¿quién sirve como soldado a sus propias expensas?) y en 2 Timoteo 2:4 (ningún soldado se enreda en los negocios de la vida civil).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76776, 'spa', 'Capitán, magistrado, comandante', 'Capitán, magistrado, comandante. El capitán de la guardia del templo, el oficial al mando de la fuerza de seguridad levítica en el templo de Jerusalén. Negocia con Judas (Lucas 22:4), dirige el grupo de arresto (Lucas 22:52) y confronta la predicación de los apóstoles (Hechos 4:1; 5:24, 26). Esta era una de las posiciones de mayor rango en la jerarquía del templo después del sumo sacerdote.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76780, 'spa', 'soldado — Un militar profesional, referido predominantemente a soldados romanos ', 'soldado — Un militar profesional, referido predominantemente a soldados romanos en las narraciones del NT. Presentes en la crucifixión: burlándose, echando suertes por las vestiduras y traspasando el costado de Jesús (Mt 27:27; Jn 19:23, 32, 34), y custodiando el sepulcro (Mt 28:12). En Hechos, soldados protegen y escoltan a Pablo durante motines, conspiraciones y naufragios (Hch 21:32; 23:23, 31; 27:31, 42). Pablo reutiliza la imagen metafóricamente para la milicia espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76786, 'spa', 'volverse físicamente — El sentido físico predominante', 'volverse físicamente — El sentido físico predominante: girar el cuerpo o volverse hacia alguien. Jesús se vuelve para dirigirse a Pedro (Mt 16:23), se gira para ver a la mujer que lo tocó (Mt 9:22) y se vuelve para mirar a la multitud que lo seguía (Lc 7:9, 44). El participio aoristo pasivo στραφείς (''habiéndose vuelto'') aparece repetidamente como marcador narrativo que introduce el discurso directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76787, 'spa', 'volver o dirigir algo — El uso transitivo', 'volver o dirigir algo — El uso transitivo: volver o dirigir algo o a alguien. Mateo 5:39 instruye al golpeado en la mejilla derecha a ''volver (στρέψον) la otra también'', un mandato de redirigir el propio cuerpo como acto de no resistencia. Apocalipsis 11:6 habla de los dos testigos con autoridad para ''convertir (στρέψαι) las aguas en sangre.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76791, 'spa', 'devolver o restituir — Un único caso que denota la devolución o restitución de a', 'devolver o restituir — Un único caso que denota la devolución o restitución de algo: Judas ''devolvió'' (ἔστρεψεν) las treinta piezas de plata a los principales sacerdotes (Mt 27:3). Este uso extiende la metáfora raíz de girar: aquí la plata vuelve por el camino por el que vino, revirtiendo la transacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76792, 'spa', 'volverse espiritual o metafóricamente — La extensión metafórica o espiritual', 'volverse espiritual o metafóricamente — La extensión metafórica o espiritual: volverse en sentido moral o espiritual. Mateo 18:3 presenta la célebre exigencia de Jesús: ''si no os volvéis (στραφῆτε) y os hacéis como niños, no entraréis en el reino de los cielos.'' Juan 12:40 cita a Isaías sobre corazones que se niegan a volverse (στραφῶσιν) para ser sanados. Hechos 13:46 registra a Pablo y Bernabé volviéndose a los gentiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76798, 'spa', 'Gorrión', 'El gorrión común, pequeña ave paseriforme proverbialmente barata e insignificante. En las cuatro ocurrencias del NT (Mt 10:29, 10:31; Lc 12:6-7), sirve como contraste retórico de la providencia divina: se vendían dos gorriones por un asarión o cinco por dos asarios, y sin embargo ni uno solo cae sin la voluntad del Padre. Todas las grandes tradiciones de traducción lo vierten con la palabra local para gorrión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76799, 'spa', 'Extender, esparcir', 'Extender o esparcir sobre el suelo — colocar mantos, ramas o coberturas a lo largo de un camino como acto de honor. En Mat 21:8 y Mar 11:8, las multitudes extendieron (ἔστρωσαν) sus mantos y seguían tendiendo (ἐστρώννυον) ramas cortadas por el camino para la entrada de Jesús en Jerusalén. Este uso transmite un acto público y ceremonial de homenaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76800, 'spa', 'Amueblar, preparar sala', 'Amueblar o preparar una habitación — disponer un espacio con sus enseres y coberturas para dejarlo listo. En Marcos 14:15 y Lucas 22:12, Jesús dice a los discípulos que hallarán un gran aposento alto ''amueblado'' (ἐστρωμένον), preparado para la cena de Pascua. El participio perfecto indica que la preparación completa ya ha sido realizada, más allá de simplemente extender algo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76801, 'spa', 'Hacer la cama', 'Hacer la cama — extender la ropa de cama o disponer un lugar para dormir. En Hechos 9:34, Pedro ordena al paralítico Eneas: ''Hazte tu cama'' (στρῶσον σεαυτῷ), siendo el acto mismo la prueba de la sanidad milagrosa. Este mandato preserva el carácter doméstico y personal: un hombre postrado que ahora puede cuidar de sí mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76805, 'spa', 'Columna, pilar', 'Pilar o columna que sirve de soporte estructural, usado metafóricamente de personas o comunidades que sostienen y estabilizan. En Gá 2:9, los apóstoles de Jerusalén son «columnas» —figuras que cargan el peso de la iglesia primitiva. En 1 Tim 3:15, la iglesia es «columna y fundamento de la verdad», y en Ap 3:12 el vencedor se convierte en columna inamovible en el templo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76807, 'spa', 'vosotros (plural)', 'Pronombre de segunda persona plural (''vosotros'') en todos los casos, usado al dirigirse a multiples individuos. La evidencia multilingue es decisiva: espanol ''a vosotros / os,'' frances ''vous / a vous,'' aleman ''euch,'' todos marcan la pluralidad de forma inequivoca. Predomina en la ensenanza de Jesus a grupos: Mt 10:15 (''os digo''), Mt 10:19 (''lo que habeis de decir''), Mt 12:31 (''os digo, todo pecado sera perdonado'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76809, 'spa', 'tu (singular)', 'Pronombre de segunda persona singular (''tu'') en todos los casos, dirigido a una sola persona. Espanol ''de ti,'' frances ''de toi,'' aleman ''deiner,'' todos confirman la singularidad. Aparece en interpelacion personal directa: el angel a Jose sobre Maria (Mt 1:20), Jesus a Satanas (Mt 4:10 ''al Senor tu Dios adoraras''), e instruccion intima (Mt 6:6 ''cuando tu ores'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76835, 'spa', 'Parentela y linaje', 'Los tres usos neotestamentarios subrayan la realidad social de las redes de parentesco: las costumbres de nombres vinculadas a la familia (Lucas 1:61), el llamado divino a dejar la propia parentela (Hechos 7:3) y la familia extendida reunida en la migración a Egipto (Hechos 7:14). El parentesco definía la ubicación social, la identidad y la obligación en el mundo antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76836, 'spa', 'Pariente o familiar de sangre, abarcando lazos familiares inmediatos (Elisabet y', 'Pariente o familiar de sangre, abarcando lazos familiares inmediatos (Elisabet y María, Lucas 1:36), el círculo de parientes en un nacimiento (Lucas 1:58), y un parentesco étnico más amplio (los ''parientes según la carne'' de Pablo, Romanos 9:3; 16:7, 11, 21). Un solo sentido familiar que cubre todos los contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76846, 'spa', 'Convocar, reunir', 'Convocar, reunir o llamar a juntarse a un grupo con un propósito específico, ya sea una asamblea formal, una formación militar o una celebración gozosa. La estructura compuesta (σύν + καλέω) subraya la idea de congregarse. Jesús convoca a los Doce para comisionarlos (Lucas 9:1), y el pastor y la mujer reúnen a vecinos para celebrar (Lucas 15:6, 9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76861, 'spa', 'Encerrar, confinar', 'Encerrar, atrapar o confinar juntamente, tanto en sentido físico como teológico-jurídico. Literalmente, en Lc 5:6 una enorme cantidad de peces queda encerrada (συνέκλεισαν) en las redes. Teológicamente, Pablo usa las formas activa y pasiva para describir el confinamiento deliberado de Dios: la Escritura «encerró todas las cosas bajo pecado» (Gá 3:22) y la ley mantenía a todos «encerrados» antes de que la fe fuera revelada (Gá 3:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76862, 'spa', 'Coheredero', 'Un coinheritor, quien participa conjuntamente en una herencia. El término siempre denota la recepción compartida de un don o promesa divina. En Rom 8:17, los creyentes son coherederos con Cristo (συγκληρονόμοι Χριστοῦ), compartiendo tanto sus padecimientos como su gloria. Ef 3:6 señala la inclusión de los gentiles como «coherederos» de la promesa abrahámica junto con Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76863, 'spa', 'Participación conjunta', 'Los tres usos neotestamentarios advierten contra la participación indebida (tinieblas, pecado) y alaban la participación justa (sufrimiento por Cristo). El prefijo «junto» (συν-) destaca que compartir en algo crea comunidad: en el mal te hace culpable, y en la aflicción te hace compañero de camino. Participar implica solidaridad profunda con aquello en lo que se toma parte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76864, 'spa', 'Copartícipe', 'Partícipe conjunto o compañero en una realidad común. En Rom 11:17, los creyentes gentiles se convierten en «copartícipes» (συγκοινωνός) de la raíz rica del olivo, injertados en las bendiciones del pacto de Israel. En 1 Cor 9:23, Pablo hace todo «por causa del evangelio» para ser copartícipe de él. Fil 1:7 describe a los filipenses como copartícipes de Pablo en la gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76866, 'spa', 'Comparar e interpretar', 'Los dos contextos difieren: 1 Corintios 2:13 enfatiza la combinación interpretativa (palabras dadas por el Espíritu para verdades reveladas por el Espíritu), mientras que 2 Corintios 10:12 critica la comparación autorreferencial (medirse a sí mismos por sí mismos, no por Cristo). Ambos implican poner cosas en relación para juzgarlas o explicarlas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76869, 'spa', 'Gozarse con otro', 'Compartir el gozo con otra persona o grupo, uniéndose a su alegría ante un suceso dichoso. La evidencia multilingüe es notablemente uniforme — francés ''se réjouir avec'', alemán ''sich mitfreuen'', español ''regocijaos conmigo'' — todas resaltan la dimensión participativa y comunitaria. En las parábolas de Lucas 15:6, 9 describe a los vecinos convocados a celebrar la recuperación de algo perdido, mientras que en 1 Corintios 12:26 se extiende al gozo mutuo dentro del cuerpo de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76875, 'spa', 'Confundir o alborotar', 'Causar confusión o tumulto, ya sea el desconcierto interno de una multitud que no logra asimilar lo que presencia (Hch 2:6, el milagro multilingüe de Pentecostés) o el caos externo de una turba amotinada (Hch 19:32; 21:27). Las cinco apariciones neotestamentarias se encuentran en Hechos, reflejando la agitación que acompañó la expansión de la Iglesia primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76878, 'spa', 'Convivir en unión', 'Los usos paulinos vinculan el vivir compartido con el morir compartido: los creyentes unidos a Cristo en la muerte comparten su vida resucitada (Ro 6:8, 2 Ti 2:11), y el vínculo de Pablo con Corinto implica un destino compartido —morir juntos o vivir juntos (2 Co 7:3). La palabra subraya que la vida en común con Cristo nace de la muerte en común con él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76880, 'spa', 'Argumentar, disputar', 'Argumentar, disputar. Argumentar, disputar o debatir de manera contenciosa con un adversario. Los escribas disputan con los discípulos mientras Jesús está en el monte (Marcos 9:14, 16), los oponentes de Esteban en la sinagoga no pueden resistir su sabiduría y disputan con él (Hechos 6:9), y Pablo disputa en Damasco tras su conversión (Hechos 9:29). Las traducciones multilingües convergen en términos confrontacionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76881, 'spa', 'Discutir, indagar juntos', 'Discutir, indagar juntos. Discutir, conferenciar o cuestionar juntos de manera inquisitiva o deliberativa. Cuando Jesús enseña con autoridad en Capernaúm, la multitud se pregunta entre sí ''¿Qué es esto?'' (Marcos 1:27), los discípulos discuten el significado de ''resucitar de entre los muertos'' (Marcos 9:10), y los Doce debaten quién podría traicionar a Jesús (Lucas 22:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76894, 'spa', 'Higuera', 'Higuera: la higuera (Ficus carica), un arbol frutal ubicuo en la agricultura mediterranea y central en la imagineria biblica. Las referencias literales describen su brotacion como presagio del verano (Mt 24:32; Mc 13:28; Lc 21:29). Su aparicion mas dramatica es la maldicion de Jesus a la higuera sin fruto cerca de Jerusalen (Mt 21:19-21; Mc 11:13-21), ampliamente entendida como un acto profetico contra la esterilidad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76897, 'spa', 'Higo', 'El higo, fruto de la higuera (Ficus carica), usado tanto como referencia agrícola concreta como metáfora de la fecundidad moral y espiritual. En Mt 7:16 y Lc 6:44, los higos aparecen en la enseñanza de Jesús de que el verdadero carácter se conoce por su fruto: «no se recogen higos de los espinos». Mc 11:13 narra cómo Jesús se acercó a una higuera buscando fruto y no halló ninguno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76901, 'spa', 'Conversar, hablar con', 'Hablar o conversar con alguien en un intercambio verbal mutuo, en contexto narrativo o informal. En la Transfiguración, Moisés y Elías hablan con Jesús (Mat 17:3; Mar 9:4; Luc 9:30), evento registrado por los tres Sinópticos con συλλαλέω. Lucas 4:36 lo usa para el murmullo asombrado de la multitud tras un exorcismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76903, 'spa', 'Conferir, deliberar', 'Conferir o deliberar en un contexto oficial o judicial, con matiz de consulta formal antes de tomar una decisión. En Hechos 25:12, tras la apelación de Pablo al César, Festo confiere (συλλαλήσας) con su consejo consultivo antes de pronunciar su fallo. La gravedad deliberativa distingue este uso de la conversación casual, subrayando la solemnidad del proceso de toma de decisiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76906, 'spa', 'Prender, arrestar, capturar', 'Prender, arrestar, capturar: apoderarse fisicamente de una persona (como prisionero) o capturar peces o animales. Este sentido dominante (9 apariciones) se centra en los relatos de arresto: la multitud prende a Jesus con espadas y palos (Mt 26:55; Mc 14:48), los oficiales lo arrestan en el huerto (Jn 18:12), y Pedro es apresado por Herodes (Hch 12:3). La pesca milagrosa en Lucas 5:9 usa el mismo verbo para la captura de peces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76907, 'spa', 'Concebir, quedar embarazada', 'Concebir, quedar embarazada: usado de una mujer que recibe vida en su vientre o, metaforicamente, del pecado que ''concibe'' la muerte. Cinco apariciones se concentran en las narrativas de la infancia de Lucas: Elisabet concibiendo a Juan (Lc 1:24, 36), el anuncio del angel a Maria (Lc 1:31), y la designacion del nombre de Jesus despues de haber sido ''concebido en el vientre'' (Lc 2:21). Santiago 1:15 extiende la metafora: el deseo ''concibe'' y da a luz el pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76908, 'spa', 'Ayudar, asistir', 'Ayudar, asistir: literalmente ''tomar juntos con'' alguien, preservando el prefijo συν- en su fuerza cooperativa. Dos apariciones: los pescadores hacen senas a sus companeros para que vengan a ''ayudarles'' a recoger la pesca (Lc 5:7), y Pablo pide a su colaborador que ''ayude'' a ciertas mujeres que trabajaron con el en el evangelio (Fil 4:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76920, 'spa', 'Recoger, juntar', 'Recoger, juntar o cosechar elementos dispersos, típicamente en contextos de siega o clasificación, llevándolos a un mismo lugar. Casi todos los usos neotestamentarios aparecen en las parábolas de Jesús: recoger uvas de espinos (Mateo 7:16; Lucas 6:44), la cizaña para quemarla (Mateo 13:28-30, 40-41) y los peces buenos de la red (Mateo 13:48).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76929, 'spa', 'Suceder, acontecer', 'Suceder, ocurrir, acontecer o sobrevenir, describiendo eventos que tienen lugar, a menudo con un matiz de importancia. Lucas 24:14 lo emplea para los trascendentales sucesos que los discípulos de Emaús comentan; Hechos 3:10 para el asombro ante la sanidad del mendigo. 1 Pedro 4:12 lo aplica a la prueba de fuego que sobreviene a los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76937, 'spa', 'Conversar, debatir', 'Conversar, conferir o debatir con otros, literalmente ''lanzar palabras juntos''. En Acts 4:15 los miembros del Sanedrín conferían entre sí, y en Acts 17:18 filósofos epicúreos y estoicos ''discutían con'' Pablo. Las traducciones españolas ''conferían'' y ''discutían'' subrayan el carácter deliberativo de estos intercambios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76938, 'spa', 'Encontrarse, toparse', 'Encontrarse con alguien, ya sea en un contexto militar hostil o en una reunión pacífica. Luke 14:31 presenta a un rey evaluando si puede ''encontrar'' a una fuerza opositora, mientras Acts 20:14 describe el encuentro pacífico con Pablo en Asos. La imagen raíz de dos partes ''lanzadas juntas'' subyace tanto a encuentros hostiles como amistosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76940, 'spa', 'Ayudar, contribuir', 'Contribuir, ayudar o asistir, un uso en voz media que significa ''aportar la parte propia junto a otros''. Acts 18:27 dice que Apolos ''contribuyó grandemente'' (συνεβάλετο) a los creyentes mediante su don de argumentación. El español ''ayudó'' destaca la dimensión cooperativa y de apoyo, distinta del mero encuentro o debate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76942, 'spa', 'Meditar, ponderar', 'Ponderar o considerar interiormente, dando vueltas a las cosas en el corazón. En Luke 2:19 María ''meditaba'' (συμβάλλουσα) las palabras de los pastores, ''juntando'' mentalmente los eventos y su significado. El español ''meditando'' confirma que se trata de un proceso reflexivo e interiorizado, no de una conversación externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76944, 'spa', 'Unir, entrelazar', 'Entrelazar o unir en un todo orgánico, dicho especialmente del cuerpo espiritual de Cristo. En Ef 4:16 todo el cuerpo está ''siendo cohesionado'' por cada coyuntura y ligamento; en Col 2:19 los creyentes están unidos a la Cabeza; y en Col 2:2 los corazones son ''unidos en amor''. Transmite una unidad corporativa y estructural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76945, 'spa', 'Instruir, enseñar', 'Instruir o enseñar reuniendo información para la comprensión de alguien. En 1 Co 2:16, Pablo cita Is 40:13 LXX: ''¿Quién conoció la mente del Señor para instruirlo (συμβιβάσαι)?'' El camino semántico de ''juntar'' a ''instruir'' pasa por la idea de ensamblar hechos hasta que surge el entendimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76947, 'spa', 'Presentar, sacar adelante', 'Hacer comparecer o empujar a alguien a una situación pública. En Hch 19:33, durante el motín de los plateros en Éfeso, los judíos ''sacaron'' (συνεβίβασαν) a Alejandro de entre la multitud para que hablara en su defensa. Este sentido es el más cercano a la raíz etimológica de conducir físicamente a alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76948, 'spa', 'Demostrar, probar', 'Demostrar o probar reuniendo evidencias en un argumento convincente. En Hch 9:22, Saulo recién convertido ''demostraba'' (συμβιβάζων) que Jesús es el Cristo, confundiendo a los judíos de Damasco con su razonamiento escritural. El sentido lógico surge naturalmente de ''reunir'' premisas para alcanzar una conclusión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76949, 'spa', 'Concluir, inferir', 'Concluir o inferir juntando observaciones. En Hch 16:10, tras la visión del hombre macedonio, ''concluimos'' (συμβιβάζοντες) que Dios los había llamado a predicar el evangelio allí. Este es el uso más abstracto de la raíz: reunir la evidencia de una visión y extraer su significado mediante razonamiento inferencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76950, 'spa', 'Aconsejar o conspirar', 'Aconsejar, deliberar o tramar, abarcando desde la orientación benévola hasta la conspiración hostil según el contexto. En Mt 26:4, los principales sacerdotes y ancianos «deliberaron juntos» (συνεβουλεύσαντο) para prender a Jesús con engaño; en Hch 9:23 los judíos de Damasco «conspiraron» para matar a Pablo. Jn 18:14 recuerda el consejo (συμβουλεύσεν) de Caifás, y Ap 3:18 presenta el consejo misericordioso de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76951, 'spa', 'Consejo, consulta, complot', 'Consejo, consulta o complot: el acto de deliberar conjuntamente, por lo general con intención hostil o estratégica. Aparece siempre en la frase συμβούλιον λαμβάνειν o συμβούλιον διδόναι (''tomar consejo'' o ''dar consejo''). Los fariseos toman consejo para destruir a Jesús (Mateo 12:14), para atraparlo con el tributo (Mateo 22:15) y los sacerdotes conspiran para condenarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76952, 'spa', 'Consejo de asesores', 'Un consejo de asesores: el cuerpo formal reunido para asesorar a un oficial de gobierno, correspondiente al latín consilium. En Hechos 25:12 el gobernador romano Festo consulta ''con su consejo'' (μετὰ τοῦ συμβουλίου) antes de dictaminar que Pablo sería enviado al César. Aquí el término pasa de una acción abstracta a un organismo concreto de gobierno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76954, 'spa', 'Simeón (nombre propio)', 'Nombre propio hebreo (Συμεών, de שִׁמְעוֹן) aplicado a varios individuos en el NT: el anciano devoto que bendijo al niño Jesús en el templo (Lc 2:25, 34), un antepasado de Jesús en la genealogía de Lucas (Lc 3:30), Simeón llamado Níger en Antioquía (Hch 13:1) y el apóstol Pedro bajo su nombre hebraico (Hch 15:14; 2 P 1:1). Todas las traducciones lo tratan como transliteración indeclinable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76958, 'spa', 'Testificar conjuntamente', 'Las traducciones conservan el compuesto: espanol «dar testimonio juntamente/conmigo», frances «temoigner avec», aleman «mitbezeugen». Los tres usos paulinos presentan un testimonio dual: conciencia y ley juntas, Espiritu y espiritu juntos, conciencia y Espiritu juntos. El «con» es esencial: un testimonio aislado podria dudarse, pero la corroboracion mutua lo confirma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76968, 'spa', 'Llevar consigo', 'Llevar a alguien consigo como compañero o colaborador, especialmente para viaje o misión. En Hch 12:25, Bernabé y Saulo llevan consigo (συμπαραλαβόντες) a Juan Marcos desde Jerusalén, una selección deliberada. La aguda disputa en Hch 15:37-38 gira en torno a este verbo: Bernabé quería «llevar consigo» (συμπαραλαβεῖν) a Marcos, pero Pablo se negó a «llevar consigo» a quien los había abandonado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76974, 'spa', 'Llenar o cumplirse', 'Las traducciones oscilan entre cumplimiento y llenado: espanol «cumplirse/se llenaban», frances «accomplir/remplir». Los tres usos muestran tanto el llenado literal (la barca con agua) como el cumplimiento temporal (tiempos senalados que llegan). La teologia lucana del calendario divino aparece en 9:51 y Hechos 2:1, donde los dias se «cumplen» segun el plan predeterminado de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76975, 'spa', 'Ahogar o sofocar', 'Ahogar o apretar estrechamente hasta sofocar el crecimiento o el movimiento. En las parábolas sinópticas, los espinos ''ahogan'' la palabra sembrada, imagen poderosa de cómo las angustias y las riquezas sofocan la fecundidad espiritual (Mt 13:22; Mc 4:7, 19; Lc 8:14). En Lc 8:42, el sentido físico se extiende a la multitud que apretaba a Jesús hasta casi impedirle avanzar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76977, 'spa', 'Viajar juntos', 'Caminar juntos, acompañar o viajar en compañía de alguien. En Marcos 10:1, las multitudes «se reúnen» con Jesús y Él les enseña mientras viajan. Lucas 7:11 describe a los discípulos y una gran multitud «yendo con» Jesús a la ciudad de Naín, preparando la escena para la resurrección del hijo de la viuda. Lucas 14:25 señala que grandes multitudes «iban con» Jesús, lo cual motiva Su exigente enseñanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76980, 'spa', 'Ser provechoso, ser ventajoso', 'Ser provechoso, ser ventajoso: ser provechoso, beneficioso o conveniente — usado impersonalmente para indicar lo que es ventajoso para alguien (16 apariciones). Jesus lo usa para advertir que perder una mano es mejor que perder todo el cuerpo (Mt 5:29-30), y Caifas lo invoca politicamente (Jn 11:50). Pablo apela a ello para el discernimiento etico: ''Todo es licito, pero no todo es provechoso'' (1 Co 6:12; 10:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76983, 'spa', 'Reunir, recoger', 'Reunir, recoger: juntar o recoger en un solo lugar — el sentido literal y activo del verbo compuesto. Aparece solo en Hechos 19:19, donde los que practicaban artes magicas ''trajeron'' sus pergaminos y los quemaron publicamente. El pasaje dramatiza vividamente la etimologia de la palabra: traer cosas juntas en un acto concreto y fisico de renuncia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76993, 'spa', 'Acordar, concordar', 'Llegar a un acuerdo mutuo, armonizar o corresponder, ya sea en el contexto de oración conjunta (Matt 18:19, donde dos creyentes que concuerdan reciben lo que piden), términos contractuales (Matt 20:2, 13, el acuerdo salarial de la viña), compatibilidad material (Luke 5:36, un remiendo que no ''combina''), o acuerdo conspirativo (Acts 5:9, Safira poniéndose de acuerdo con Ananías para engañar). La imagen etimológica de voces sonando al unísono subyace en todos estos usos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77004, 'spa', 'con, en compañía de', 'Preposición que rige dativo para expresar compañía, asociación y acción compartida. En contextos narrativos marca acompañamiento físico — Jesús ''con'' sus discípulos (Mateo 26:35), criminales crucificados ''con'' él (Mateo 27:38). En la teología paulina adquiere una profunda fuerza participativa: los creyentes están ''con Cristo'' en su muerte, sepultura y resurrección (Romanos 6:8; Colosenses 2:12-13; 1 Tesalonicenses 4:17). El español ''con'' y ''contigo'' cubren todo el espectro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77005, 'spa', 'Reunirse, congregarse', 'El sentido intransitivo o medio/pasivo: personas que se reunen, se congregan o son agrupadas. Grandes multitudes ''se reunieron'' en torno a Jesus (Mateo 13:2), los fariseos ''se congregaron'' para interrogarlo (Mateo 22:34, 41) y los primeros creyentes se reunian en comunidad. El espanol ''se reunieron'' / ''habiendose reunido'' captura esta cualidad reflexiva del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77008, 'spa', 'Reunir, recoger (transitivo)', 'Sentido transitivo y activo: reunir, recoger o juntar personas o cosas deliberadamente. Herodes ''reunio'' a los sacerdotes (Mateo 2:4), los angeles ''reuniran'' a los elegidos (Mateo 24:31) y los agricultores recogen trigo en graneros (Mateo 3:12; 6:26). El espanol ''Recoged'' (imperativo) destaca la iniciativa del agente en la metafora agricola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77017, 'spa', 'Acoger, dar hospitalidad', 'Un sentido figurado extendido que significa acoger, recibir o dar hospitalidad a un forastero, encontrado exclusivamente en la parabola de las ovejas y los cabritos (Mateo 25:35, 38, 43). Aqui ''recoger'' a alguien significa recibirlo en el propio hogar y cuidado. El espanol ''me recogisteis'' desplaza la metafora espacial de congregar una multitud a albergar a un individuo necesitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77035, 'spa', 'Sinagoga, asamblea judia', 'Lugar de asamblea judia para culto, oracion y lectura de la Tora. Jesus ensena y sana en sinagogas por toda Galilea (Mateo 4:23; 9:35), Pablo las visita primero en cada nueva ciudad (Hechos 13:5; 17:1-2) y sirven como escenarios de proclamacion y persecucion. El espanol sinagoga es prestamo directo del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77041, 'spa', 'Reunir o congregar', 'Los idiomas convergen: espanol «reunidos/reuniendo», frances «rassembler». Los tres usos neotestamentarios describen una asamblea fisica: creyentes reunidos con gozo (Lc 24:33), en oracion (Hch 12:12), u obreros congregados para una confrontacion (Hch 19:25). El verbo destaca el acto de juntar lo que estaba disperso en un solo lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77042, 'spa', 'Ajustar cuentas', 'Traduccion uniforme: espanol «ajustar/ajusta», frances «compter». Las parabolas de Mateo presentan el momento de la rendicion de cuentas, cuando el senor llama a revision y evalua la fidelidad. El verbo capta tanto el proceso (revisar el libro mayor) como el resultado (liquidacion final, ya sea perdon o juicio). La imagen financiera se vuelve escatologica: Dios saldara cuentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77043, 'spa', 'Companero de cautiverio', 'Todos los idiomas preservan el compuesto: espanol «companero de prision/co-prisionero», frances «compagnon de captivite», aleman «Mitgefangene». El uso constante de Pablo como titulo honorifico transforma la prision de verguenza en insignia de fidelidad. Estos companeros de prision comparten no solo celdas sino sufrimiento centrado en Cristo, haciendo del encarcelamiento una forma de companerismo evangelico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77044, 'spa', 'Acompañar de cerca', 'Los tres usos de Marcos destacan a quienes acompañaban deliberadamente a Jesús, no como simples espectadores sino caminando con Él. Las mujeres que «le seguían» desde Galilea (Lc 23:49) muestran un compañerismo sostenido, siendo testigos tanto de su ministerio como de su crucifixión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77047, 'spa', 'Reclinarse a la mesa', 'Reclinarse juntos para compartir una comida, participando de la comunión de mesa según la postura de banquete grecorromana. Se usa para describir a Jesús cenando con publicanos y pecadores (Mt 9:10; Mr 2:15), a los invitados en el banquete de cumpleaños de Herodes (Mt 14:9; Mr 6:22) y a otros comensales que presencian eventos significativos durante la cena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77053, 'spa', 'Asociarse socialmente', 'Los tres usos de Pablo prohíben la convivencia social con pecadores flagrantes o creyentes insubordinados, no para condenarlos sino para preservar la pureza de la comunidad y generar presión hacia el arrepentimiento. La «mezcla» prohibida incluye compartir la mesa, señal de comunión íntima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77055, 'spa', 'Encontrarse, toparse', 'Encontrarse con otra persona cara a cara, ya sea por disposición previa o por providencia. En Heb 7:1, Melquisedec ''habiendo encontrado'' (συναντήσας) a Abraham tras la derrota de los reyes es un momento clave en el argumento sobre el sacerdocio; en Luke 9:37 y Acts 10:25 se trata de encuentros narrativos con multitudes e individuos. Luke 22:10 usa el futuro para un encuentro proféticamente dispuesto por Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77056, 'spa', 'Sobrevenir, suceder', 'Dicho de eventos, circunstancias o experiencias que ''salen al encuentro'' de una persona, es decir, que le sobrevienen o suceden. Es una extensión metafórica natural: lo que físicamente te encuentra en el camino también puede encontrarte como destino o providencia. En Acts 20:22 Pablo dice que no sabe ''las cosas que me sucederán'' (τὰ συναντήσοντά μοι) en Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77061, 'spa', 'Ser arrastrado colectivamente', 'Los usos paulinos advierten contra la influencia negativa del grupo: la hipocresía que incluso contagió a Bernabé (Gá 2:13) y el error doctrinal que arrastra a los inconstantes (2 P 3:17). Los creyentes deben resistir la presión social que los aparta de la verdad y la integridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77062, 'spa', 'Morir juntamente', 'Los tres usos abarcan desde la promesa fallida de Pedro (Mr 14:31) hasta el profundo vínculo de Pablo con Corinto (2 Co 7:3) y la unión del creyente con Cristo (2 Ti 2:11). Morir juntos, ya sea literalmente o mediante la identificación bautismal, forja una conexión indestructible y garantiza un destino común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77066, 'spa', 'Arrebatar por fuerza', 'Apresar con violencia y arrastrar, apoderarse mediante una fuerza abrumadora. En Lucas 8:29 el endemoniado gadareno es repetidamente «arrebatado» por el espíritu inmundo, una experiencia violenta e involuntaria. En Hechos 6:12, los opositores «prendieron» a Esteban y lo arrastraron ante el concilio; en Hechos 19:29, la turba efesia «arrebató» a Gayo y Aristarco. Hechos 27:15 aplica el término al navío atrapado por la tempestad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77068, 'spa', 'Vínculo o ligamento', 'Lazo, ligamento, vínculo unificador: la atadura concreta o metafórica que mantiene las partes unidas. En Colosenses 2:19 y Efesios 4:3, Pablo lo emplea para los tendones del cuerpo y el vínculo espiritual de la paz que une a los creyentes. En Hechos 8:23, Pedro invierte la imagen: Simón el Mago está preso en una «atadura de maldad».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77071, 'spa', 'Consiervo, compañero de servicio', 'Consiervo, compañero de servicio. Un consiervo que comparte el mismo amo, usado tanto en contextos parabólicos donde los siervos tienen obligaciones ante un señor común (Mateo 18:28–33; 24:49) como título de solidaridad entre obreros cristianos que sirven juntos a Cristo (Colosenses 1:7; 4:7). En Apocalipsis, los ángeles se lo aplican a sí mismos en relación con los profetas humanos y los creyentes (Apocalipsis 6:11; 19:10; 22:9), subrayando que ángeles y humanos fieles comparten el mismo servicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77077, 'spa', 'Co-resurrección espiritual', 'La teología paulina de la unión con Cristo alcanza aquí su clímax: si los creyentes murieron con Cristo (Ro 6), también resucitaron con Él. El «juntamente» no es mera simultaneidad sino unión orgánica: su resurrección se convierte en la nuestra, y su vida resucitada fluye hacia los que están en Él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77078, 'spa', 'concilio, Sanedrín — El consejo judío de gobierno y justicia, referido principal', 'concilio, Sanedrín — El consejo judío de gobierno y justicia, referido principalmente al Sanedrín de Jerusalén que juzgó a Jesús (Mt 26:59; Mc 14:55) y después a los apóstoles (Hch 4:15; 5:21; 6:12). El plural (Mt 10:17; Mc 13:9) se extiende a los tribunales locales de las sinagogas. Jesús advirtió a sus discípulos que serían ''entregados a los concilios'', usando el plural para incluir tribunales judíos locales con autoridad disciplinaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77081, 'spa', 'La facultad moral interior que evalúa las propias acciones y motivaciones, dando', 'La facultad moral interior que evalúa las propias acciones y motivaciones, dando testimonio junto con la razón y la ley. Pablo fundamenta la responsabilidad moral de los gentiles en la conciencia (Rom 2:15) y discute extensamente la ''conciencia débil'' respecto a los alimentos ofrecidos a ídolos (1 Cor 8:7-12; 10:25-29). Hebreos contrasta la incapacidad de los sacrificios animales para purificar la conciencia con la sangre de Cristo que limpia de obras muertas (Heb 9:9, 14; 10:22). Las Epístolas Pastorales valoran la ''buena conciencia'' como marca de fe genuina (1 Tim 1:5, 19; 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77086, 'spa', 'Ser consciente, percatarse', 'Ser consciente de algo, darse cuenta, comprender: denota tanto una percepción privada interior como un conocimiento compartido con otra persona. En Hechos 5:2, Safira comparte el conocimiento del fraude con Ananías; en 1 Corintios 4:4, Pablo habla de su propia autoconciencia ante Dios. Hechos 12:12 y 14:6 emplean el participio aoristo para una percatación repentina: «habiéndose dado cuenta».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77095, 'spa', 'Colaborar o cooperar', 'Trabajar conjuntamente con alguien o algo, cooperar o colaborar hacia una meta compartida. El sujeto puede ser divino (el Señor obrando junto a los apóstoles, Mc 16:20), providencial (todas las cosas cooperando para bien, Ro 8:28) o humano (creyentes trabajando juntos en el ministerio, 1 Co 16:16; 2 Co 6:1). Santiago 2:22 lo aplica a la fe y las obras operando al unísono.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77096, 'spa', 'Adjetivo sustantivado que designa a quien trabaja junto a otro, usado por Pablo ', 'Adjetivo sustantivado que designa a quien trabaja junto a otro, usado por Pablo como término casi técnico para los compañeros de ministerio en la empresa del evangelio. Aplicado tanto a individuos como a grupos: Priscila y Aquila (Romanos 16:3), Urbano (Romanos 16:9), Timoteo (Romanos 16:21), Tito (2 Corintios 8:23), Epafrodito (Filipenses 2:25), y los creyentes en Corinto que son ''colaboradores de Dios'' (1 Corintios 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77100, 'spa', 'reunirse, congregarse — El sentido predominante de asamblea comunitaria', 'reunirse, congregarse — El sentido predominante de asamblea comunitaria: juntarse, congregarse o reunirse en un lugar para adoración, deliberación o propósito compartido. Pablo reprende a los corintios por su conducta ''cuando os reunís'' para la Cena del Señor (1 Co 11:20). En Hechos, el verbo describe repetidamente las reuniones de la iglesia primitiva (Hch 1:6; 2:6), y en los Evangelios, las multitudes agolpándose alrededor de Jesús (Mc 3:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77101, 'spa', 'acompañar, ir con — Viajar junto con alguien o acompañarlo, enfatizando el movim', 'acompañar, ir con — Viajar junto con alguien o acompañarlo, enfatizando el movimiento compartido hacia un destino más que una reunión estática. Cuando las mujeres ''que habían venido con él desde Galilea'' siguieron a Jesús hasta la cruz (Lc 23:55), o cuando Pedro invitó a los hombres de Jope a ''ir con'' él a casa de Cornelio (Hch 10:23), el verbo resalta la compañía en el camino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77118, 'spa', 'unirse sexualmente — Uso eufemístico que denota la unión sexual o cohabitación e', 'unirse sexualmente — Uso eufemístico que denota la unión sexual o cohabitación entre marido y mujer. Aparece en Mt 1:18 — ''antes de que se juntasen'' — describiendo la consumación del matrimonio con reserva digna, un uso bien atestiguado en el griego clásico (cf. LSJ).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77123, 'spa', 'Comer juntos', 'Comer junto con alguien, expresando aceptación social, comunión y solidaridad comunitaria. En el NT, cada aparición tiene carga teológica: la mesa compartida de Jesús con pecadores (Lc 15:2) expresaba la bienvenida divina; los apóstoles comiendo con el Cristo resucitado confirmaba su testimonio (Hch 10:41); y las disputas sobre quién podía comer con quién marcaron momentos decisivos en la historia de la iglesia primitiva (Hch 11:3; Gá 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77124, 'spa', 'Entendimiento, discernimiento', 'La facultad de comprensión rápida y discernimiento: la capacidad de captar significados, percibir conexiones y ejercer buen juicio. Abarca desde la agudeza intelectual hasta la sabiduría espiritual. En Lc 2:47 describe la asombrosa capacidad del niño Jesús para comprender y responder a los doctores de la ley. Pablo ora por ella en Col 1:9 como don espiritual esencial para la vida cristiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77127, 'spa', 'Inteligente, entendido', 'Inteligente, perspicaz, dotado de entendimiento: describe a una persona con capacidad de comprender y sintetizar. En Mateo 11:25 y Lucas 10:21, Jesús lo emplea en un contexto paradójico donde la inteligencia mundana se contrasta con la fe sencilla. Hechos 13:7 lo aplica elogiosamente al procónsul romano Sergio Paulo. La cita de Isaías 29:14 en 1 Corintios 1:19 apunta contra la autosuficiencia intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77128, 'spa', 'Consentir, aprobar conjuntamente', 'Dar el consentimiento, unirse en la aprobación o expresar solidaridad con una acción o práctica, cargando el peso moral de la complicidad o el respaldo compartido. Luke 11:48 condena a quienes ''consienten en'' el asesinato de los profetas; Acts 8:1 y 22:20 describen la complicidad de Saulo en la lapidación de Esteban; Rom 1:32 extiende la culpa a quienes ''aprueban'' el pecado aun sin cometerlo. El uso positivo en 1 Cor 7:12 muestra la versatilidad del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77134, 'spa', 'Constreñir o compeler interiormente', 'Constreñir o compeler interiormente: ser presionado o acorralado por una fuerza interna urgente. Pablo confiesa que el amor de Cristo le ''constriñe'' (2 Corintios 5:14, συνέχει), y está ''apretado'' entre vivir y partir (Filipenses 1:23). Jesús mismo dice ''cuán angustiado estoy'' hasta que su bautismo de sufrimiento se cumpla (Lucas 12:50).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77136, 'spa', 'Apretar físicamente, agolparse', 'Apretar físicamente, agolparse: una multitud que presiona contra alguien desde todos los lados. La muchedumbre ''aprieta'' a Jesús tan estrechamente que él pregunta quién le tocó (Lucas 8:45). En Lucas 19:43, los enemigos ''te estrecharán'' y te apretarán por todos los costados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77137, 'spa', 'Sujetar, asir o tapar', 'Sujetar, asir o tapar: retener físicamente a una persona o cerrar algo por la fuerza. Los que arrestaron a Jesús lo ''sujetaban'' y se burlaban de él (Lucas 22:63); la multitud ''tapó'' sus oídos contra el testimonio de Esteban (Hechos 7:57).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77138, 'spa', 'Afligir o sujetar por enfermedad o angustia', 'Afligir o sujetar por enfermedad o angustia: ser preso o agarrado por una dolencia o emoción abrumadora en un sentido pasivo de padecimiento. La suegra de Simón estaba ''presa'' de una gran fiebre (Lucas 4:38); los gadarenos fueron ''sobrecogidos'' de gran temor (Lucas 8:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77147, 'spa', 'Costumbre establecida', 'Los tres usos neotestamentarios muestran la costumbre operando en distintos niveles: cívico (la amnistía pascual de Pilato), personal (efectos persistentes de hábitos idolátricos) y eclesiástico (la práctica de la iglesia sobre el velo). En cada caso, la práctica establecida —ya sea por ley, trasfondo cultural o tradición— genera una fuerza normativa que condiciona la conducta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77153, 'spa', 'entender, comprender, percibir — Captar el significado o la importancia de algo ', 'entender, comprender, percibir — Captar el significado o la importancia de algo mediante percepción mental y espiritual; literalmente ''juntar las piezas'' en la mente. Central en el discurso sinóptico de las parábolas: el oyente de buena tierra ''oye y entiende'' (Mt 13:23), mientras la profecía de Isaías advierte sobre oír sin entender (Mt 13:13-15; Hch 28:26-27). Jesús prueba la comprensión de los discípulos: ''¿Aún no entendéis?'' (Mt 15:16; 16:9; Mc 8:17, 21). Lucas añade el momento del día de la resurrección cuando Jesús ''les abrió el entendimiento para comprender las Escrituras'' (Lc 24:45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77165, 'spa', 'Demostrar o probar', 'Demostrar o probar: mostrar una cualidad o verdad mediante evidencia concreta o accion. Cuatro apariciones llevan esta fuerza probatoria: Dios ''demuestra'' su amor en la muerte de Cristo por los pecadores (Ro 5:8), la injusticia humana ''prueba'' la justicia de Dios (Ro 3:5), los corintios ''demostraron'' su inocencia al manejar una crisis (2 Co 7:11), y reedificar lo que fue derribado ''prueba'' la transgresion (Ga 2:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77166, 'spa', 'Recomendar o encomendar', 'Recomendar o encomendar: presentar favorablemente a alguien, introduciendo a una persona o causa con aprobacion y respaldo. Este sentido mas frecuente (9 apariciones) aparece en la recomendacion de Pablo de Febe a los romanos (Ro 16:1), su rechazo a ''recomendarnos a nosotros mismos'' como los falsos apostoles que llevan cartas de recomendacion (2 Co 3:1; 5:12), y su declaracion de que los apostoles se recomiendan ''en todo'' como ministros de Dios (2 Co 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77169, 'spa', 'Mantener unido o subsistir', 'Mantener unido o subsistir: cohesionar o subsistir como un todo unificado — el sentido intransitivo o estativo de ''estar juntos''. Tres apariciones llevan este peso cosmico y fisico: en Cristo ''todas las cosas subsisten'' (Col 1:17), los cielos ''existian desde antiguo'' sostenidos por la palabra de Dios (2 P 3:5), y Pedro y sus companeros ''estaban con'' Jesus en la Transfiguracion, completamente despiertos (Lc 9:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77186, 'spa', 'Ordenar con autoridad', 'Los tres usos en Mateo muestran dirección autoritativa: Jesús mandando las acciones de sus discípulos (21:6, 26:19) e incluso el dinero de la traición de Judas cumpliendo lo que los profetas «ordenaron» (27:10). El verbo porta tanto la precisión militar de disponer en orden como la autoridad jerárquica de quien tiene potestad para mandar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77187, 'spa', 'Consumación del siglo', 'La consumación o culminación final de un período, empleada en el Nuevo Testamento casi exclusivamente para el fin escatológico de la era presente (συντέλεια τοῦ αἰῶνος). Solo Mateo concentra cinco de las seis apariciones: las parábolas de la cosecha en Matt 13:39-40, 49, la pregunta del Discurso del Olivete en Matt 24:3, y la promesa final de la Gran Comisión en Matt 28:20. Heb 9:26 complementa el uso señalando que Cristo apareció ''en la consumación de los siglos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77189, 'spa', 'Completar, terminar', 'Llevar a cabo activamente una tarea, período o secuencia de acciones hasta su conclusión. En Lucas 4:13, el diablo se aparta ''habiendo completado'' (syntelesas) toda tentación, y en Lucas 4:2 los cuarenta días de ayuno ''se cumplieron'' (syntelesthesisōn). Romanos 9:28 lo usa para describir al Señor ejecutando y ''completando'' (syntelōn) su palabra sobre la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77192, 'spa', 'Consumar un pacto', 'Establecer o consumar un pacto, referido específicamente al acto divino de llevar un acuerdo solemne a pleno efecto. En Hebreos 8:8 (citando Jeremías 31:31), el Señor declara ''consumaré'' (syntelesō) un nuevo pacto con la casa de Israel. No se trata de simplemente terminar algo, sino de llevarlo a su plena realización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77193, 'spa', 'Cumplirse, consumarse', 'Alcanzar el cumplimiento divinamente señalado, usado en voz pasiva o media para eventos proféticos o períodos rituales que llegan a su destino. En Marcos 13:4, los discípulos preguntan cuándo ''se cumplirán'' (synteleisthai) las señales escatológicas; en Hechos 21:27, los siete días de purificación ''estaban por cumplirse'' (syntelesthēsan).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77196, 'spa', 'Preservar con cuidado', 'Los tres usos abarcan la custodia protectora (Herodes guardando a Juan a pesar de querer matarlo, Marcos 6:20), la preservación contemplativa (María atesorando y meditando, Lucas 2:19) y la conservación práctica (odres nuevos conservan el vino nuevo, Mateo 9:17). En cada caso se trata de guardar algo valioso con atención deliberada, protegiéndolo de deterioro o destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77197, 'spa', 'Acordar, conspirar', 'Acordar conjuntamente, hacer un pacto, conspirar — describe un arreglo mutuo entre varias partes, frecuentemente con matices de secretismo o intención hostil. En Lucas 22:5, los principales sacerdotes acuerdan el precio de la traición; en Juan 9:22, las autoridades ya han pactado la expulsión de quien confiese a Jesús. Hechos 23:20 describe una conspiración para emboscar a Pablo, y Hechos 24:9 registra a los adversarios uniéndose al ataque.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77199, 'spa', 'Confluir apresuradamente', 'Los tres usos muestran tanto convergencia literal (multitudes corriendo hacia Jesús, gente acudiendo a los apóstoles) como un curso compartido en sentido figurado (los gentiles esperando que los creyentes «corran con» ellos hacia el pecado). El verbo capta tanto el movimiento físico como la urgencia colectiva de dirigirse juntos hacia un mismo destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77200, 'spa', 'Quebrar, aplastar, destrozar', 'Quebrar, aplastar o destrozar algo mediante fuerza física activa: el sentido transitivo centrado en el agente. En Marcos 14:3 una mujer quiebra un frasco de alabastro para ungir a Jesús, un acto de adoración mediante destrucción deliberada. Lucas 9:39 describe un demonio que magulla a un muchacho. Romanos 16:20 lo eleva a escala cósmica: ''Dios aplastará a Satanás''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77201, 'spa', 'Ser quebrado, quebrantado', 'Ser quebrado, quebrantado o destrozado en sentido pasivo o resultativo, describiendo el estado de algo ya roto o la experiencia de ser aplastado. Mateo 12:20 cita Isaías 42:3: ''la caña cascada no quebrará'', donde el participio describe algo ya dañado. Marcos 5:4 relata cadenas ''destrozadas'' por el endemoniado gadareno. Lucas 4:18 extiende la imagen a los oprimidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77217, 'spa', 'Siria (topónimo)', 'Provincia romana al norte de Palestina cuya capital Antioquía fue el primer gran centro del cristianismo gentil. La fama de Jesús se extendió por toda Siria al inicio de su ministerio (Mt 4:24), y el concilio de Jerusalén dirigió su carta a los creyentes de Antioquía y Siria (Hch 15:23). Lucas ancla la natividad mencionando al gobernador Cirenio (Lc 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77223, 'spa', 'Arrastrar con fuerza', 'Arrastrar o jalar con fuerza, tirando de algo o alguien por el suelo o a través del espacio. La palabra conlleva connotaciones de violencia o gran esfuerzo físico. En Jn 21:8, los discípulos arrastran una red llena de peces; en Hechos describe el brutal arrastre de personas: Saulo llevando creyentes a prisión (8:3), Pablo arrastrado fuera de Listra tras ser apedreado (14:19), Jasón arrastrado ante los magistrados (17:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77229, 'spa', 'Crucificar juntamente', 'Ser crucificado junto con alguien, usado tanto literalmente de los ejecutados en cruces al lado de Jesús (Mt 27:44; Mc 15:32; Jn 19:32) como teológicamente de la muerte participativa del creyente con Cristo. El uso paulino en Ro 6:6 y Gá 2:20 expresa la idea radical de que en la unión bautismal, el viejo hombre sufre co-crucifixión con Cristo, muriendo al dominio del pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77239, 'spa', 'Matanza sacrificial', 'Los tres usos neotestamentarios emplean la metáfora de ovejas llevadas al matadero: Cristo como el siervo sufriente (Hechos 8:32), los creyentes muertos por su fidelidad (Romanos 8:36) y los ricos que inconscientemente se engordan para el juicio divino (Santiago 5:5). La imagen es visceral: víctimas indefensas, muerte violenta y sangre derramada como signo de inocencia sacrificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77241, 'spa', 'Degollar, inmolar, matar', 'Degollar, inmolar, matar. Matar por medios violentos, con la connotación original de degüello o carnicería, aplicado tanto al asesinato (Caín matando a Abel, 1 Juan 3:12) como a la inmolación sacrificial (el Cordero ''inmolado'', Apocalipsis 5:6, 9, 12; 13:8). Apocalipsis lo usa también para la violencia escatológica: al jinete del caballo rojo se le da poder para que los hombres ''se maten unos a otros'' (Apocalipsis 6:4, 9; 18:24). El participio perfecto pasivo ἐσφαγμένον subraya el estado permanente de haber sido inmolado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77248, 'spa', 'En extremo, muchísimo', 'En extremo, muchísimo. Adverbio intensivo que significa ''en extremo, muchísimo, en gran manera'', amplificando la fuerza de emociones, reacciones y estados. Mateo lo favorece para momentos dramáticos: el gozo inmenso de los magos (Mateo 2:10), el terror de los discípulos en la Transfiguración (Mateo 17:6), su profunda tristeza ante las predicciones de traición (Mateo 17:23; 26:22), el asombro ante la enseñanza sobre las riquezas (Mateo 19:25) y la angustia de los siervos en la parábola del deudor (Mateo 18:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77250, 'spa', 'Poner un sello sobre alguien o algo como marca de autenticación, propiedad o apr', 'Poner un sello sobre alguien o algo como marca de autenticación, propiedad o aprobación divina. Este es predominantemente un sentido teológico en el NT: Dios sella a los creyentes con el Espíritu Santo (2 Corintios 1:22; Efesios 1:13; 4:30), el Padre ha sellado al Hijo (Juan 6:27), y creer es ''poner su sello'' de que Dios es verdadero (Juan 3:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77254, 'spa', 'Sellar algo cerrándolo', 'Sellar algo cerrándolo: clausurar, asegurar u ocultar contenidos para que no puedan ser accedidos ni leídos. Aplicado al sellado físico de la tumba de Cristo (Mateo 27:66), la clausura de visiones proféticas (Apocalipsis 22:10 contrasta con el rollo sellado de Daniel), y la atadura de Satanás en el abismo sellado sobre él (Apocalipsis 20:3). El énfasis recae en la restricción y el cierre más que en la autenticación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77260, 'spa', 'Sello, sigilo o la impresión dejada por uno, utilizado para autenticar, asegurar', 'Sello, sigilo o la impresión dejada por uno, utilizado para autenticar, asegurar o certificar. En sentido literal se refiere a impresiones de cera o arcilla que cierran y validan documentos o tumbas. Pablo lo emplea metafóricamente: la circuncisión es un sello de la justicia por fe (Rom 4:11), y los convertidos son el sello del ministerio apostólico (1 Cor 9:2). En Apocalipsis, siete sellos aseguran el rollo escatológico que solo el Cordero puede abrir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77264, 'spa', 'Casi, aproximadamente', 'Las lenguas coinciden: español «casi», inglés «almost», francés «presque», alemán «beinahe». Los tres usos neotestamentarios emplean el adverbio para señalar una cuasi-totalidad sin afirmar universalidad absoluta: casi toda la ciudad (Hch 13:44), casi toda Asia (19:26), casi todo (Heb 9:22). El adverbio reconoce excepciones mientras enfatiza la regla predominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77266, 'spa', 'Rasgar, partir, hender — desgarramiento o separación física de objetos materiale', 'Rasgar, partir, hender — desgarramiento o separación física de objetos materiales. El velo del templo se rasga en dos en la crucifixión (Mateo 27:51; Marcos 15:38; Lucas 23:45), los cielos se abren en el bautismo de Jesús (Marcos 1:10), las rocas se parten (Mateo 27:51) y las redes de pesca se rompen bajo el peso de una pesca milagrosa (Juan 21:11). La parábola de Jesús advierte contra rasgar tela nueva para remendar la vieja (Lucas 5:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77270, 'spa', 'Dividir (un grupo) — división figurada de un grupo en facciones o partidos opues', 'Dividir (un grupo) — división figurada de un grupo en facciones o partidos opuestos. En Hechos 14:4, la población de Iconio «fue dividida»: unos a favor de los apóstoles y otros de los dirigentes judíos. De modo similar, Pablo divide deliberadamente al Sanedrín planteando la cuestión de la resurrección (Hechos 23:7). La metáfora pasa de la hendidura física a la fractura social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77274, 'spa', 'División, cisma', 'División o cisma entre personas: un desacuerdo que fractura a una comunidad en facciones opuestas. Es el sentido dominante en el NT, con seis apariciones. En Jn 7:43, 9:16 y 10:19 describe a la multitud dividida respecto a Jesús. Pablo suplica unidad en 1 Co 1:10 y lamenta las divisiones en las asambleas corintias (1 Co 11:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77276, 'spa', 'Rotura, rasgadura', 'Rasgadura o rotura en un tejido: el sentido literal y físico de un desgarro en un material. Jesús advierte en Mt 9:16 y Mr 2:21 que coser tela sin encoger sobre un vestido viejo provoca que el remiendo tire, empeorando la rotura. Solo dos pasajes atestiguan este sentido, pero la imagen textil concreta subyace a la metáfora comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77278, 'spa', 'Desocupado o dedicado', 'El espectro semántico va desde la vacuidad peligrosa hasta la dedicación deliberada. Los usos neotestamentarios muestran una casa desocupada lista para la reocupación demoníaca (Mt 12:44; Lc 11:25) y tiempo liberado intencionalmente para la oración (1 Co 7:5). El verbo es neutro en sí mismo: estar «libre» puede implicar vacío peligroso o consagración espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77280, 'spa', 'salvar espiritualmente', 'Sentido teológico primario de librar del pecado, la muerte espiritual y el juicio divino, concediendo vida eterna mediante la fe. Este uso abrumadoramente dominante (79 de 108 ocurrencias) abarca desde el anuncio del ángel de que Jesús ''salvará a su pueblo de sus pecados'' (Mateo 1:21) hasta las promesas escatológicas como ''el que persevere hasta el fin será salvo'' (Mateo 24:13). En todas las lenguas principales converge el campo léxico de la liberación soteriológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77282, 'spa', 'rescatar del peligro', 'Rescate físico de un peligro inminente, una amenaza o la muerte — el clamor de los discípulos en la tormenta: ''¡Señor, sálvanos, que perecemos!'' (Mateo 8:25), o Pedro hundiéndose en las olas (Mateo 14:30). Incluye también el desafío burlón en la cruz: ''¡Sálvate a ti mismo y desciende!'' (Mateo 27:40). El español emplea ''salvar'' en imperativo y condicional, mientras que el árabe recurre a najjā/jallaṣa en este sentido de rescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77283, 'spa', 'restaurar por la fe', 'La declaración distintiva ''tu fe te ha salvado/sanado'' (Mateo 9:22; Marcos 5:34; Marcos 10:52; Lucas 7:50; Lucas 8:48), que tiende un puente entre la sanación física y la liberación espiritual en un solo pronunciamiento. Este sentido es notoriamente difícil de traducir porque se niega a separar cuerpo y alma. El árabe oscila entre jallaṣa (salvar) y shafā (sanar) según el énfasis teológico del traductor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77303, 'spa', 'sanar, curar', 'Curación de enfermedad física, restauración de la salud corporal, donde el contexto deja claro que se trata de recuperación física y no de salvación espiritual. La mujer con flujo de sangre que extiende la mano al manto de Jesús: ''Si tan solo toco su manto, seré sanada'' (Mateo 9:21; Marcos 5:28), y los resúmenes de sanaciones masivas (Marcos 6:56). El español distingue con claridad este sentido mediante ''sanar'' frente a ''salvar.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77326, 'spa', 'cuerpo (físico)', 'El cuerpo humano físico como totalidad organizada, abarcando el cuerpo vivo, el cadáver, el cuerpo resucitado y — mediante extensión metafórica paulina — la iglesia como cuerpo corporativo de Cristo (1 Corintios 12:12-27; Efesios 1:23). A diferencia de σάρξ (carne), σῶμα no conlleva connotación de fragilidad moral. El uso neotestamentario preserva siempre la idea de un todo orgánico e integrado, ya sea físico o comunitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77337, 'spa', 'Salvador — Título que significa ''libertador'' o ''rescatador'', aplicado en el Nuev', 'Salvador — Título que significa ''libertador'' o ''rescatador'', aplicado en el Nuevo Testamento tanto a Dios Padre como a Jesucristo en cuanto agentes de salvación. De Dios: el Magnificat de María (Lc 1:47) y repetidamente en las Pastorales — ''Dios nuestro Salvador'' (1 Ti 1:1; 2:3; Tit 1:3; 2:10; 3:4). De Cristo: el anuncio angélico del nacimiento (Lc 2:11), la confesión de los samaritanos ''el Salvador del mundo'' (Jn 4:42), la predicación de Pedro (Hch 5:31) y la esperanza escatológica de Filipenses (Fil 3:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77340, 'spa', 'Liberación, preservación y salvación en el sentido más pleno, abarcando el resca', 'Liberación, preservación y salvación en el sentido más pleno, abarcando el rescate pasado (la obra consumada de Cristo), la experiencia presente (la vida continua de fe) y la consumación futura (la esperanza escatológica). Zacarías canta sobre un ''cuerno de salvación'' levantado en la casa de David (Luc 1:69, 71), Pablo identifica el evangelio como ''poder de Dios para salvación'' (Rom 1:16), y el autor de Hebreos presenta la salvación como herencia definitiva (Heb 1:14; 2:3; 9:28). La palabra abarca desde la liberación física hasta la redención espiritual y la consumación escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77342, 'spa', 'Salvación manifestada', 'Salvífico, que trae liberación; usado como sustantivo para designar la salvación de Dios hecha manifiesta. Simeón contempla el ''instrumento salvador'' de Dios en el niño Jesús (Lucas 2:30); la promesa isaiana de que toda carne verá la salvación de Dios se cita en Lucas 3:6 y Hechos 28:28 para enmarcar el alcance universal del evangelio. Efesios 6:17 lo emplea concretamente como el ''yelmo de la salvación'' en la armadura espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77343, 'spa', 'Estar en sano juicio', 'Poseer lucidez mental y cordura, estar en pleno uso de razón. Se usa del endemoniado gadareno tras su liberación (Marcos 5:15; Lucas 8:35), hallado ''vestido y en su sano juicio'', y por Pablo al contrastar la experiencia extática con la compostura racional (2 Corintios 5:13). Enfatiza la claridad cognitiva restaurada frente al desorden previo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77345, 'spa', 'Ser prudente y sobrio', 'Ejercer dominio propio y pensar con juicio templado. Este sentido moral aparece en la exhortación de Pablo a no pensar más alto de sí mismo, sino con cordura (Romanos 12:3), en su encargo a los jóvenes de ser prudentes (Tito 2:6), y en el llamado de Pedro a la sobriedad para la oración (1 Pedro 4:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77351, 'spa', 'Cordura y dominio propio', 'Los tres usos neotestamentarios abarcan lo apologético (Pablo defendiendo su cordura en Hch 26:25) y lo ético (el adorno modesto y la preservación de las mujeres en 1 Ti 2:9, 15). En cada caso, σωφροσύνη designa una mente disciplinada y equilibrada, ni desquiciada ni impulsiva, sino controlada y orientada hacia la virtud y la sensatez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77352, 'spa', 'Prudente, templado', 'Prudente, templado, de mente sana — describe a quien ejerce dominio sobre sus pasiones y actúa con sobrio discernimiento. En 1 Timoteo 3:2 y Tito 1:8 es requisito indispensable para los obispos; en Tito 2:2, virtud propia de varones maduros; en Tito 2:5, cualidad esperada de las mujeres jóvenes. Las Epístolas Pastorales lo vinculan consistentemente con otras virtudes de moderación y dignidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77361, 'spa', 'Una gran unidad de peso monetario que representa una suma inmensa, usada en el N', 'Una gran unidad de peso monetario que representa una suma inmensa, usada en el Nuevo Testamento exclusivamente dentro de las parábolas de Jesús para representar una vasta encomienda y rendición de cuentas. En Mateo 18:24, la deuda de 10.000 talentos dramatiza la escala incalculable del perdón divino; en Mateo 25:15-28, los talentos distribuidos a los siervos ilustran la mayordomía de los recursos dados por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77363, 'spa', 'Aposento, cuarto interior', 'Cuarto interior, aposento, despensa — un espacio cerrado y recluido, ya sea para la devoción privada, la actividad secreta o el almacenamiento. En Mateo 6:6, Jesús instruye a orar en el ταμεῖον, enfatizando la intimidad ante Dios. Mateo 24:26 y Lucas 12:3 explotan el mismo sentido de ocultamiento. Lucas 12:24 retoma el significado más antiguo de granero o despensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77364, 'spa', 'Orden, disposición', 'Disposición fija u orden establecido. En el NT tiene dos aplicaciones: (a) rango sacerdotal, como la división aarónica de Zacarías (Lc 1:8) y el sacerdocio ''según el orden de Melquisedec'' (Heb 5:6, 10; 6:20; 7:11, 17); y (b) disposición apropiada en la vida comunitaria, cuando Pablo exhorta a que todo se haga con decencia y orden (1 Co 14:40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77366, 'spa', 'Humilde, de baja condición', 'Humilde o de baja condición, describiendo una circunstancia externa (pobreza) o una postura de mansedumbre ante Dios. Jesús lo aplica a sí mismo (Mt 11:29, ''soy manso y humilde de corazón''), estableciendo la humildad como virtud. María celebra que Dios exalta a los humildes (Lc 1:52), y Pablo aconseja asociarse con los de baja condición (Ro 12:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77371, 'spa', 'Humildad genuina', 'La virtud genuina de la humildad: modestia de espíritu que estima a los demás como más importantes que uno mismo. Pablo la enumera con la mansedumbre y la paciencia como esenciales para la unidad eclesial (Ef 4:2). En Fil 2:3 se fundamenta en el ejemplo de Cristo. Col 2:18 y 2:23 muestran su distorsión: humildad fingida ligada al culto angélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77372, 'spa', 'De ánimo humilde', 'Extensión adjetival que significa ''de ánimo humilde'' o ''de disposición modesta'', describiendo la cualidad del carácter como atributo personal más que como sustantivo abstracto. En 1 Pedro 3:8, se exhorta a los creyentes a ser ταπεινόφρονες: unidos en espíritu y de ánimo humilde unos con otros. El español ''humildes'' capta este desplazamiento del sustantivo abstracto a la cualidad personal vivida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77374, 'spa', 'Ser humillado o rebajado (pasivo)', 'Ser humillado o rebajado (pasivo): experimentar humillación o reducción por mano ajena o por decreto divino. La visión profética de que ''todo monte será rebajado'' (Lucas 3:5, citando Isaías 40:4) usa el futuro pasivo, y la advertencia repetida de que ''el que se exalta será humillado'' (Mateo 23:12; Lucas 14:11; 18:14) presenta la inversión pasiva divina. Pablo sabe ''ser humillado'' (Filipenses 4:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77375, 'spa', 'Humillarse a sí mismo (medio/reflexivo)', 'Humillarse a sí mismo (medio/reflexivo): autohumillación voluntaria ante Dios como disciplina espiritual y postura de fe. Santiago ordena: ''Humillaos delante del Señor, y él os exaltará'' (Santiago 4:10), y Pedro hace eco: ''Humillaos bajo la poderosa mano de Dios'' (1 Pedro 5:6). El imperativo aoristo pasivo (ταπεινώθητε) funciona con fuerza reflexiva en ambos pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77377, 'spa', 'Humillar o rebajar (activo/transitivo)', 'Humillar o rebajar (activo/transitivo): rebajar activamente el estatus, orgullo o posición de alguien, ya sea por acción divina, circunstancia social o elección deliberada. Jesús enseña que ''el que se humille como este niño'' será el mayor en el reino (Mateo 18:4), y la fórmula repetida ''el que se exalta será humillado'' (Mateo 23:12; Lucas 14:11; 18:14) emplea este sentido como uno de los polos de la inversión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77382, 'spa', 'Humillación, bajeza', 'Humillación, bajeza, condición humilde — el estado de hallarse en una posición baja, ya sea experimentado como gracia divina, sufrimiento injusto o fragilidad mortal. Lucas 1:48 celebra la mirada bondadosa de Dios sobre la humilde condición de María. Hechos 8:33 describe la humillación judicial del Mesías. Filipenses 3:21 lo aplica a la condición mortal del cuerpo presente. Santiago 1:10 lo dirige al rico como advertencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77383, 'spa', 'Causar problema, perturbación o confusión entre otras personas, frecuentemente m', 'Causar problema, perturbación o confusión entre otras personas, frecuentemente mediante falsa enseñanza o agitación social. En Hechos 15:24 el concilio de Jerusalén reconoce que ciertos hombres «perturbaron» a los creyentes gentiles con exigencias sobre la circuncisión. Pablo advierte a los gálatas acerca de quienes los «perturban» pervirtiendo el evangelio (Gál 1:7; 5:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77384, 'spa', 'Experimentar turbación interior, temor o angustia emocional', 'Experimentar turbación interior, temor o angustia emocional. Zacarías se turbó ante la aparición del ángel (Lc 1:12), los discípulos se aterrorizaron al ver a Jesús caminar sobre el agua (Mt 14:26; Mc 6:50), y Jesús ordena a sus seguidores que no dejen que su corazón se turbe (Jn 14:1,27). Las traducciones multilingües —español «turbado», francés «troubler», alemán «beunruhigen»— subrayan esta dimensión emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77389, 'spa', 'Agitar o remover agua físicamente', 'Agitar o remover agua físicamente. En el estanque de Betesda, un ángel agitaba periódicamente el agua (Jn 5:4), y el paralítico explica que no tiene a nadie que lo meta en el estanque cuando el agua «es agitada» (Jn 5:7). Este sentido concreto y físico preserva el significado más antiguo de la palabra, desde Homero: Poseidón agitando el mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77400, 'spa', 'Ciudad de Tarso', 'El topónimo Tarso aparece tres veces en el NT, siempre vinculado a Pablo. Hechos 9:30 narra cómo los discípulos lo envían a Tarso por seguridad tras su conversión, Hechos 11:25 muestra a Bernabé yendo allí a buscarlo, y Hechos 22:3 recoge el testimonio de Pablo de haber nacido en esa ciudad. La transliteración es uniforme en las lenguas modernas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77402, 'spa', 'Designar, disponer, ordenar', 'Designar, asignar u ordenar a alguien en un cargo, posición o tarea mediante una decisión autoritativa. Incluye la subordinación militar (Mt 8:9; Lc 7:8), la delegación oficial (Hch 15:2) y la designación divina (Hch 13:48, donde los ''ordenados'' para vida eterna creyeron). La voz pasiva en Hechos 22:10 y 28:23 refleja disposiciones establecidas por una autoridad superior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77410, 'spa', 'Dedicarse a', 'Voz media: dedicarse o consagrarse voluntariamente a una tarea o servicio. En 1 Corintios 16:15, la familia de Estéfanas ''se dispuso para'' —es decir, se comprometió de forma voluntaria— al ministerio de los santos. Este sentido conserva la idea raíz de disposición ordenada pero la orienta hacia dentro como un compromiso autoimpuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77411, 'spa', 'Toro sacrificial', 'Toro, buey — un bovino macho adulto, particularmente en contextos de sacrificio o banquete. Mateo 22:4 presenta toros como provisiones de un banquete real en una parábola. Hechos 14:13 describe un sacrificio pagano en Listra, donde el sacerdote de Zeus trae toros y guirnaldas. Hebreos 9:13 y 10:4 invocan el sistema levítico para argumentar que la sangre de toros es insuficiente para la verdadera expiación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77414, 'spa', 'Tumba, sepulcro', 'Sepultura, tumba o sepulcro excavado en la roca donde se depositan los difuntos. En Mt 23:27, 29, Jesús usa la imagen de los sepulcros blanqueados como metáfora demoledora de la apariencia religiosa exterior que oculta la corrupción interior. En Mt 27:61-66 designa el sepulcro específico donde fue depositado el cuerpo de Jesús, sellado y custodiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77418, 'spa', 'Rápidamente, apresuradamente, pronto — adverbio que significa ''con rapidez, con ', 'Rápidamente, apresuradamente, pronto — adverbio que significa ''con rapidez, con prontitud, en breve'', usado positivamente para expresar urgencia apremiante (Lucas 14:21, la orden del amo de reunir invitados rápidamente; 2 Timoteo 4:9, la súplica de Pablo a Timoteo de venir pronto; Filipenses 2:19, la esperanza de enviar a Timoteo en breve) o negativamente para señalar prisa alarmante o imprudente (Gálatas 1:6, abandonar el evangelio tan rápido; 1 Timoteo 5:22, no imponer las manos con precipitación; 2 Tesalonicenses 2:2, no dejarse perturbar con facilidad).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77422, 'spa', 'Más rápidamente', 'Más rápidamente, más pronto — forma comparativa que expresa mayor velocidad o urgencia respecto al ritmo esperado. En Juan 13:27, Jesús apremia a Judas con intensidad ominosa. Juan 20:4 describe una carrera literal hacia el sepulcro vacío. Hebreos 13:19 y 13:23 reflejan el deseo vehemente del autor de reunirse prontamente con la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77424, 'spa', 'Premura, rapidez, prontitud', 'Rapidez, premura o celeridad, que funciona como adverbio temporal mediante la frase preposicional ''ἐν τάχει'' (con prontitud, pronto, sin demora). El ángel ordena a Pedro vestirse ''ἐν τάχει'' durante su escape de la cárcel (Hch 12:7), Jesús promete que Dios vindicará a sus elegidos ''ἐν τάχει'' (Lc 18:8) y Pablo asegura a los romanos que la derrota de Satanás vendrá ''ἐν τάχει'' (Ro 16:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77429, 'spa', 'Adverbio que significa rápidamente, pronto o sin demora, usado para mandatos urg', 'Adverbio que significa rápidamente, pronto o sin demora, usado para mandatos urgentes (Mateo 5:25; 28:7), urgencia parabólica (Lucas 14:21), ritmo narrativo dramático (Juan 13:27 respecto a Judas), y la promesa escatológica del retorno de Cristo (Apocalipsis 22:7, 12, 20). Un único sentido de velocidad temporal que abarca todos los contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77433, 'spa', 'y, tanto... como (enclítica)', 'Partícula coordinante enclítica que conecta palabras, frases o cláusulas, apareciendo típicamente en posición pospositiva tras la primera palabra de su cláusula. Funciona mayormente como un simple conectivo ''y'' o en la correlación τε...καί (''tanto... como''), ligando elementos en una unidad lógica más estrecha que καί por sí solo. Concentrada en Lucas-Hechos y Hebreos (Hechos 5:19, 5:42; Hebreos 1:3), refleja un registro helenístico elevado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77440, 'spa', 'Muralla, muro de ciudad', 'Muralla o muro de fortificación, la gran estructura defensiva que rodea un área urbana. A diferencia de τοῖχος (G5109), que designa la pared de un edificio, τεῖχος siempre denota una fortificación exterior de gran envergadura. La dramática huida de Pablo desde Damasco, descolgado en un canasto desde lo alto del muro, ilustra su escala física (Hch 9:25; 2 Co 11:33). La caída de los muros de Jericó por la fe resalta su dimensión militar y teológica (Heb 11:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77443, 'spa', 'Hijitos, queridos hijos', 'Diminutivo afectuoso que significa ''hijitos'' o ''queridos hijos'', usado como vocativo que transmite ternura paternal hacia los dependientes espirituales. Jesús lo emplea de manera única en la Última Cena para dirigirse a sus discípulos con intimidad antes de su partida (Jn 13:33). El apóstol Juan lo convierte en su modo distintivo de dirigirse a sus congregaciones (1 Jn 2:1, 12, 28; 3:7, 18; 4:4; 5:21), evocando cuidado pastoral y vínculo filial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77447, 'spa', 'hijo, descendiente', 'Sentido primario de hijo o descendiente, abarcando descendientes biológicos, hijos espirituales y progenie metafórica. Usado referencialmente en todos los casos y números. Jesús declara que Dios puede levantar ''hijos'' (τέκνα) a Abraham de las piedras (Mateo 3:9), y Pablo habla de los creyentes como ''hijos de la promesa'' (Gálatas 4:28). El español ''hijos,'' el francés ''enfant'' y el alemán ''Kinder'' lo traducen uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77450, 'spa', 'hijo mío (vocativo afectuoso)', 'Uso vocativo que funciona como forma afectuosa de tratamiento de un mayor a un más joven — ''hijo mío,'' ''hijitos.'' Se distingue del sentido 1 no por el referente sino por la fuerza pragmática: transmite ternura e intimidad. Jesús se dirige al paralítico como ''τέκνον'' antes de sanarlo (Marcos 2:5), y lo usa con sus discípulos (Marcos 10:24). El español ''Hijo mío'' y el alemán ''mein Kind'' captan esta calidez vocativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77464, 'spa', 'Plenamente desarrollado, completo o maduro, ya sea de personas, animales sacrifi', 'Plenamente desarrollado, completo o maduro, ya sea de personas, animales sacrificiales o cualidades abstractas. En Mt 5:48 Jesús llama a los discípulos a una integridad de amor modelada en la generosidad imparcial de Dios. Pablo distingue a los creyentes τέλειοι capaces de recibir enseñanza sólida de los infantes espirituales (1 Cor 2:6; Heb 5:14). En 1 Cor 13:10, «lo perfecto» (τὸ τέλειον) es la consumación que hace obsoletos los dones parciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77472, 'spa', 'perfeccionar, llevar a la perfección — Hacer perfecto, llevar a una persona o co', 'perfeccionar, llevar a la perfección — Hacer perfecto, llevar a una persona o cosa a la plenitud espiritual o moral. Cristo perfeccionado por medio de los padecimientos (He 2:10; 5:9), los creyentes perfeccionados en unidad (Jn 17:23), y la obra perfeccionadora de la fe descrita en Filipenses 3:12 fundamentan diecisiete ocurrencias. El peso teológico recae sobre la transformación interior hacia la madurez completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77475, 'spa', 'completar, terminar, cumplir — Completar, terminar o llevar a cabo una tarea, cu', 'completar, terminar, cumplir — Completar, terminar o llevar a cabo una tarea, curso o propósito hasta su fin previsto. Jesús terminando la obra de su Padre (Jn 4:34; 17:4), el grito de consumación en la cruz (Jn 19:28) y el niño Jesús cumpliendo los días de la fiesta (Lc 2:43) definen seis ocurrencias orientadas al cumplimiento de un objetivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77490, 'spa', 'Alcanzar el término de la vida física; morir', 'Alcanzar el término de la vida física; morir. En el NT este verbo denota consistentemente la muerte biológica en toda forma gramatical: participio aoristo (''habiendo muerto'', Mateo 2:19), imperativo presente (''que muera'', Mateo 15:4; Marcos 7:10, citando Éxodo 21:17), e indicativo aoristo en el escenario hipotético de los saduceos (Mateo 22:25; Marcos 12:20-22). La conexión etimológica con τέλος (''fin'') subraya la finalidad de la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77499, 'spa', 'completar o terminar — El sentido activo transitivo de finalizar o completar una', 'completar o terminar — El sentido activo transitivo de finalizar o completar una tarea, discurso o travesía. Mateo emplea este verbo cinco veces como transición formularia — ''Cuando Jesús terminó estas palabras'' (Mt 7:28; 11:1; 13:53; 19:1; 26:1) — marcando el cierre de cada discurso principal. Pablo igualmente dice ''he acabado la carrera'' (2 Ti 4:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77500, 'spa', 'ser consumado o cumplido — El sentido pasivo o medio de ser completado, cumplido', 'ser consumado o cumplido — El sentido pasivo o medio de ser completado, cumplido o llevado a consumación, especialmente de propósitos proféticos y designios divinos. Juan 19:28 señala que Jesús sabía que ''todas las cosas habían sido ya consumadas'', y su grito final τετέλεσται (Jn 19:30) se convirtió en la declaración definitiva de que la redención estaba completa. Lucas 18:31 lo aplica al cumplimiento de los escritos proféticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77508, 'spa', 'cumplir o llevar a cabo — Cumplir, guardar o llevar a cabo una ley, mandamiento ', 'cumplir o llevar a cabo — Cumplir, guardar o llevar a cabo una ley, mandamiento u obligación moral mediante la acción obediente. Santiago 2:8 habla de ''cumplir la ley real'', Romanos 2:27 del incircunciso que ''cumple la ley'', y Gálatas 5:16 promete que andar en el Espíritu significa no ''satisfacer'' los deseos de la carne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77511, 'spa', 'pagar — Pagar impuestos, tributo u obligación financiera — un uso concreto y tra', 'pagar — Pagar impuestos, tributo u obligación financiera — un uso concreto y transaccional. En Mateo 17:24, los cobradores del impuesto preguntan si Jesús ''paga'' el impuesto del templo de las dos dracmas, y Romanos 13:6 explica que por esta razón los creyentes ''pagan'' tributo a las autoridades. Un sentido netamente comercial, bien diferenciado de los usos teológicos y literarios del mismo verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77517, 'spa', 'Fin, conclusión o terminación de un período, proceso o estado — frecuentemente c', 'Fin, conclusión o terminación de un período, proceso o estado — frecuentemente con peso escatológico como el fin de la era. Es el sentido dominante con 36 ocurrencias, presente en las repetidas advertencias del Discurso del Olivete. La frase εἰς τέλος (''hasta el fin, por completo, finalmente'') intensifica la idea de terminación total y definitiva del orden presente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77519, 'spa', 'Impuesto, tributo aduanero o tasa recaudada por el estado — sentido clásico bien', 'Impuesto, tributo aduanero o tasa recaudada por el estado — sentido clásico bien atestiguado derivado de τέλος como ''pago debido''. Jesús pregunta a Pedro si los reyes cobran τέλη de sus propios hijos o de los extraños (Mat 17:25), y Pablo instruye a pagar τέλος a quien corresponda junto con φόρος (tributo) en Rom 13:7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77520, 'spa', 'Meta, resultado o propósito último hacia el cual algo se dirige — τέλος en su se', 'Meta, resultado o propósito último hacia el cual algo se dirige — τέλος en su sentido teleológico de resultado diseñado más que de mera cesación. Aparece en 1 Timoteo 1:5 (''el propósito del mandamiento es el amor de un corazón puro''), 1 Pedro 1:9 (''obteniendo el resultado de vuestra fe, la salvación de vuestras almas'') y en el llamado de 1 Pedro 3:8 a la unidad como τέλος de la vida comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77524, 'spa', 'Cobrador de impuestos o publicano que arrendaba el derecho de recaudar peajes y ', 'Cobrador de impuestos o publicano que arrendaba el derecho de recaudar peajes y tributos en nombre del Estado romano. Socialmente despreciado en la Palestina judía por colaborar con la potencia ocupante, estos personajes aparecen en los Evangelios como ejemplos típicos de pecadores (Mt 5:46; 9:10-11) a quienes Jesús deliberadamente se acerca como amigo. La expresión «publicanos y pecadores» se repite como fórmula retórica recurrente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77527, 'spa', 'Puesto de recaudación', 'Este término aparece exclusivamente en los relatos sinópticos del llamado de Mateo (Leví): Mateo 9:9, Marcos 2:14 y Lucas 5:27. En cada pasaje, Jesús pasa junto al τελώνιον y llama al recaudador a seguirle, quien abandona de inmediato su lucrativa posición. El puesto de cobro funciona como símbolo del paso de la avaricia al discipulado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77528, 'spa', 'Prodigio o portento', 'Prodigio o portento: una maravilla sobrenatural que produce asombro y señala el poder de Dios. Aparece casi siempre emparejado con σημεῖον («señal») en la frase fija «señales y prodigios», donde τέρας resalta la cualidad asombrosa y cautivadora de los actos divinos. Pedro cita los prodigios como acreditación divina de Jesús (Hch 2:22), y la profecía de Joel promete portentos cósmicos antes del Día del Señor (Hch 2:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77532, 'spa', 'El número cardinal cuarenta, que aparece en contextos de duración temporal carga', 'El número cardinal cuarenta, que aparece en contextos de duración temporal cargados de significado teológico. En el NT marca el ayuno de Jesús en el desierto (Mt 4:2; Mc 1:13; Lc 4:2), los cuarenta y seis años de construcción del templo (Jn 2:20) y el ministerio de cuarenta días tras la resurrección (Hch 1:3). Aunque todas las traducciones lo vierten como un simple numeral, el patrón bíblico inviste a este número de un peso teológico inconfundible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77535, 'spa', 'El número cardinal cuatro, que modifica sustantivos sin extensión semántica ni d', 'El número cardinal cuatro, que modifica sustantivos sin extensión semántica ni desplazamiento metafórico. En contextos narrativos cuantifica grupos concretos: cuatro hombres (Mar 2:3), cuatro días (Jn 11:17, 39), cuatro soldados (Jn 19:23). En la visión apocalíptica provee la arquitectura del orden cósmico: cuatro seres vivientes (Ap 4:6-8), cuatro ángeles (Ap 7:1; 9:14-15), cuatro esquinas de la tierra (Ap 7:1; 20:8). Su valor es puramente numérico sin variación semántica en todo el NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77539, 'spa', 'Cuarto (ordinal) — numeral ordinal que indica la cuarta posición en una serie', 'Cuarto (ordinal) — numeral ordinal que indica la cuarta posición en una serie. Jesús camina sobre el mar durante la cuarta vigilia (Mateo 14:25; Marcos 6:48), la visión de Cornelio ocurre a la hora cuarta (Hechos 10:30), y la cuarta criatura viviente es semejante a un águila volando (Apocalipsis 4:7). Todos los idiomas lo traducen uniformemente como ordinal simple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77541, 'spa', 'Cuarta parte (fracción) — una cuarta parte o un cuarto, donde el ordinal adquier', 'Cuarta parte (fracción) — una cuarta parte o un cuarto, donde el ordinal adquiere un sentido fraccionario o proporcional. En Apocalipsis 6:8, el jinete del caballo pálido recibe autoridad sobre ''la cuarta parte de la tierra'': no se trata del cuarto elemento en una secuencia, sino de una cuarta parte de un todo. El español ''cuarta parte'' explicita esta distinción, separando el sentido fraccionario del ordinal puramente secuencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77544, 'spa', 'Cuatro mil', 'El número cardinal cuatro mil. En los Evangelios sinópticos indica el tamaño de la multitud en la segunda alimentación milagrosa de Jesús (Mateo 15:38; Marcos 8:9) y reaparece cuando Jesús recuerda a los discípulos aquel milagro (Mateo 16:10; Marcos 8:20). Hechos 21:38 lo utiliza en un contexto político: los cuatro mil sicarios liderados por un rebelde egipcio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77545, 'spa', 'Cuatrocientos', 'Cuatrocientos — número cardinal usado en referencias históricas y cronológicas del Nuevo Testamento. Hechos 5:36 cuenta unos cuatrocientos seguidores del rebelde Teudas. Hechos 7:6 evoca los cuatrocientos años de peregrinación profetizados a Abraham (cf. Gn 15:13). Hechos 13:20 marca el período de los jueces. Gálatas 3:17 establece la prioridad cronológica de la promesa sobre la ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77548, 'spa', 'Animal cuadrúpedo', 'Las tres apariciones forman dos contextos distintos: la visión de Pedro en Hechos 10:12 y 11:6, donde un lienzo contiene «toda clase de cuadrúpedos» como parte de la revelación divina sobre lo puro e impuro, y Romanos 1:23, donde los cuadrúpedos figuran entre las imágenes degradantes que los humanos adoran en lugar de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77549, 'spa', 'Gobernar como tetrarca', 'Las tres apariciones se encuentran en el mismo versículo (Lucas 3:1), enumerando a los tetrarcas que gobernaban distintas regiones cuando Juan el Bautista inició su ministerio: Herodes tetrarca de Galilea, Felipe tetrarca de Iturea y Traconítide, y Lisanias tetrarca de Abilene. Este triple uso demuestra la cuidadosa documentación histórica de Lucas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77550, 'spa', 'Gobernante regional', 'Gobernante regional designado bajo la autoridad imperial romana, que regía una porción de un territorio dividido con rango subordinado al de rey. Las cuatro apariciones en el NT (Mt 14:1; Lc 3:19; 9:7; Hch 13:1) se refieren a gobernantes herodianos en Palestina. Las traducciones multilingües transliteran uniformemente el término, confirmando que era un título político fijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77552, 'spa', 'Arte, oficio o profesión', 'Las tres apariciones abarcan contextos diversos: Hechos 17:29 trata sobre objetos «formados por el arte y la imaginación humana» en el discurso de Pablo en Atenas, contrastando los ídolos fabricados con el Dios vivo. Hechos 18:3 señala que Pablo compartía el mismo oficio (fabricación de tiendas) con Aquila y Priscila. Apocalipsis 18:22 lamenta que en la Babilonia caída no se hallará artesano de ningún oficio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77553, 'spa', 'Artesano o artífice', 'Trabajador experto, artesano o maestro constructor que da forma a materiales según su conocimiento técnico. En Hechos 19:24,38 identifica a Demetrio y sus compañeros plateros como comerciantes artesanos. Hebreos 11:10 lo aplica metafóricamente a Dios como diseñador y constructor de la ciudad con fundamentos, mientras Apocalipsis 18:22 lo emplea en un lamento por la industria perdida de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77556, 'spa', 'Tan grande', 'Demostrativo enfático que indica grado o magnitud extraordinarios — ''tan grande'', ''tan poderoso''. Cada aparición en el NT (2 Co 1:10; Heb 2:3; Stg 3:4; Ap 16:18) intensifica al sustantivo que acompaña, ya sea una amenaza, una salvación, un navío o un terremoto. Las traducciones multilingües lo leen uniformemente como amplificador escalar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77557, 'spa', 'Observar o cumplir', 'El sentido más frecuente en el NT: observar, obedecer o guardar mandamientos, enseñanzas, palabras o la ley con fiel atención. El hindi मानना (''obedecer'') y el árabe حفظ confirman la noción de adherencia cuidadosa. Se ejemplifica en Mt 28:20 (''enseñándoles a guardar todo lo que os he mandado'') y Jn 8:51 (''si alguno guarda mi palabra, no verá muerte jamás'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77560, 'spa', 'Custodiar o proteger', 'Guardar, vigilar o proteger a una persona o cosa contra daño, pérdida o fuga. Es el núcleo del griego clásico: Aristófanes y Tucídides lo usan para custodiar murallas y vigilar prisioneros. En el NT, Jesús declara que ha ''guardado'' a sus discípulos en el nombre del Padre (Jn 17:12), y soldados son puestos a ''custodiar'' el sepulcro (Mt 27:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77572, 'spa', 'Custodia continua', 'Única aparición en Hch 12:5 donde Pedro ''era custodiado'' en la cárcel: el pasivo imperfectivo subraya la naturaleza continua e ininterrumpida de su detención. Aunque está estrechamente relacionado con el sentido de protección (sentido 2), la evidencia multilingüe (español era-custodiado, alemán bewahrt) muestra que los traductores lo tratan como un estado sostenido más que como un acto puntual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77574, 'spa', 'Reservar para el futuro', 'Reservar o preservar algo para un tiempo o propósito futuro, generalmente en construcciones pasivas. Pedro habla de una herencia ''guardada en los cielos para vosotros'' (1 Pe 1:4) y de los cielos y la tierra ''reservados para el fuego'' (2 Pe 3:7). El énfasis recae en algo mantenido en un estado de espera hasta su momento señalado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77601, 'spa', 'Custodia y observancia', 'Dos apariciones describen el encarcelamiento físico: Hechos 4:3 y 5:18 relatan cómo los apóstoles fueron puestos en custodia por las autoridades religiosas de Jerusalén, una detención temporal destinada a intimidar y controlar. En marcado contraste, 1 Corintios 7:19 emplea el término para la observancia de los mandamientos de Dios, no como prisión sino como devoción obediente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77602, 'spa', 'Ciudad de Tiberias', 'Las tres apariciones se encuentran en el Evangelio de Juan. Juan 6:1 identifica el mar de Galilea como «mar de Tiberias», proporcionando un referente geográfico para lectores gentiles. Juan 6:23 menciona barcas procedentes de Tiberias que llegan al sitio de la alimentación de los cinco mil. Juan 21:1 usa nuevamente «mar de Tiberias» para ubicar la aparición del Resucitado donde Jesús restaura a Pedro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77604, 'spa', 'poner, colocar, depositar', 'Significado físico nuclear: poner, colocar o depositar un objeto o una persona en un lugar. Abarca colocar una lámpara sobre un candelero (Marcos 4:21), depositar un cuerpo en un sepulcro (Mateo 27:60) y poner enemigos debajo de los pies (Mateo 22:44). La fisicidad es siempre concreta — algo se mueve y se sitúa en una ubicación determinada. El español emplea ''poner,'' ''colocar'' y ''depositar'' según el registro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77610, 'spa', 'dar la vida', 'Expresión idiomática especializada, τίθημι τὴν ψυχήν (''poner/dar la vida''), que denota la muerte sacrificial voluntaria. Casi las nueve ocurrencias se concentran en Juan 10:11-18 y 1 Juan 3:16. El idioma es joánico y cristológico, centrado en la entrega libre del Buen Pastor. El español recurre a ''poner la vida'' o ''dar la vida,'' captando la voluntariedad del acto sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77619, 'spa', 'designar, establecer', 'Extensión metafórica al nombramiento o establecimiento en un cargo o posición de autoridad. Jesús dice a los discípulos ''yo os he puesto'' para que llevéis fruto (Juan 15:16); Dios ''puso'' a Pablo como luz a los gentiles (Hechos 13:47); el Espíritu Santo ''constituyó'' a los ancianos como obispos (Hechos 20:28). El árabe pasa de waḍaʿa a jaʿala (hacer/designar), señalando una clara separación semántica de la colocación física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77626, 'spa', 'decidir, proponerse', 'Modismo de resolución mental: fijar algo en el corazón o proponerse un curso de acción (τίθημι ἐν τῇ καρδίᾳ o τίθημι βουλήν). Pablo ''se propuso en el Espíritu'' ir a Jerusalén (Hechos 19:21); los marineros ''decidieron'' encallar la nave (Hechos 27:12). La colocación física se ha interiorizado por completo — uno deposita una decisión dentro de la propia voluntad. El español emplea ''proponer'' y ''resolver.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77665, 'spa', 'Dar a luz, traer un hijo al mundo desde el vientre', 'Dar a luz, traer un hijo al mundo desde el vientre. Este es el sentido dominante, abarcando los nacimientos de Jesús (Mt 1:21,25; Lc 2:7), Juan el Bautista (Lc 1:57) y el hijo apocalíptico de Apocalipsis 12. La expresión española «dar a luz» —literalmente «dar a la luz»— capta bellamente el sentido de traer a la visibilidad. La palabra lleva peso y ternura: es el verbo elegido para la Encarnación misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77670, 'spa', 'Nacer', 'Nacer: la perspectiva pasiva del mismo acontecimiento. En Mt 2:2 los magos preguntan «¿Dónde está el que ha nacido Rey de los judíos?» y en Lc 2:11 el ángel anuncia «os ha nacido hoy un Salvador». El cambio de activa a pasiva destaca la llegada del niño al mundo más que el trabajo de parto de la madre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (77674, 'spa', 'Producir o dar fruto, cosechas o vegetación', 'Producir o dar fruto, cosechas o vegetación: una extensión metafórica o botánica. En Heb 6:7, la tierra que bebe la lluvia y «produce» una cosecha útil para quienes la cultivan recibe la bendición de Dios. Esta única ocurrencia muestra cómo la metáfora del nacimiento puede extenderse naturalmente del vientre a la tierra.');